// Modular multiplication, c=a*b mod 2p
// prime p in 59-radix limbs
// n0 = -p^{-1} mod 2^59
#define N0 ((spint)0xa49acaab6ab709u)

// Modular multiplication using CIOS Montgomery method
// Inputs a, b are in Montgomery form; output c is also in Montgomery form
// Result is kept modulo 2p (no final subtraction of p)
static void modmul(const spint *a, const spint *b, spint *c) {
  spint t[278] = {0};
  spint mask = ((spint)1 << 59u) - (spint)1;
  int i, j;

  for (i = 0; i < 278; i++) {
    dpint C = (dpint)t[0] + (dpint)a[0] * b[i];
    spint q = ((spint)C * N0) & mask;
    C += (dpint)q * p_limb[0];
    C >>= 59u;
    for (j = 1; j < 278; j++) {
      C += (dpint)t[j] + (dpint)a[j] * b[i] + (dpint)q * p_limb[j];
      t[j - 1] = (spint)C & mask;
      C >>= 59u;
    }
    t[277] = (spint)C;
  }

  for (i = 0; i < 278; i++) {
    c[i] = t[i];
  }
}

// Modular squaring using CIOS Montgomery method
// Input a is in Montgomery form; output c is also in Montgomery form
// Result is kept modulo 2p (no final subtraction of p)
static void modsqr(const spint *a, spint *c) {
  spint t[278] = {0};
  spint mask = ((spint)1 << 59u) - (spint)1;
  int i, j;

  for (i = 0; i < 278; i++) {
    dpint C = (dpint)t[0] + (dpint)a[0] * a[i];
    spint q = ((spint)C * N0) & mask;
    C += (dpint)q * p_limb[0];
    C >>= 59u;
    for (j = 1; j < 278; j++) {
      C += (dpint)t[j] + (dpint)a[j] * a[i] + (dpint)q * p_limb[j];
      t[j - 1] = (spint)C & mask;
      C >>= 59u;
    }
    t[277] = (spint)C;
  }

  for (i = 0; i < 278; i++) {
    c[i] = t[i];
  }
}

// copy
static void modcpy(const spint *a, spint *c) {
  int i;
  for (i = 0; i < 278; i++) {
    c[i] = a[i];
  }
}

// square n times
